// ─── Scene 1: Clicks Dropping — animated downward line chart ─────────────────
// "Clicks are dropping. Rankings haven't changed. Impressions are up."
// ~5s * 25 = 125 frames

const Scene1: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const overallIn = spring({ frame, fps, delay: 0, config: { damping: 200 } });

  // Animate line drawing progress
  const lineProgress = interpolate(frame, [5, 100], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Chart data points for a declining clicks line
  const clicksPoints = [
    { x: 0, y: 0 },
    { x: 0.12, y: -0.05 },
    { x: 0.25, y: -0.12 },
    { x: 0.38, y: -0.22 },
    { x: 0.5, y: -0.35 },
    { x: 0.62, y: -0.42 },
    { x: 0.75, y: -0.55 },
    { x: 0.88, y: -0.65 },
    { x: 1.0, y: -0.78 },
  ];

  const chartW = 1200;
  const chartH = 400;

  const getXY = (pt: { x: number; y: number }) => ({
    x: pt.x * chartW,
    y: chartH / 2 + pt.y * chartH,
  });

  // Build SVG path
  const buildPath = (progress: number) => {
    const totalPoints = clicksPoints.length;
    const segments = totalPoints - 1;
    const progressIndex = progress * segments;
    const pointCount = Math.floor(progressIndex) + 2;
    const capped = Math.min(pointCount, totalPoints);

    const pts = clicksPoints.slice(0, capped).map(getXY);
    if (pts.length < 2) return "";

    // Interpolate last point
    const lastIdx = Math.floor(progressIndex);
    if (lastIdx < segments) {
      const frac = progressIndex - lastIdx;
      const a = getXY(clicksPoints[lastIdx]);
      const b = getXY(clicksPoints[lastIdx + 1]);
      pts[pts.length - 1] = {
        x: a.x + (b.x - a.x) * frac,
        y: a.y + (b.y - a.y) * frac,
      };
    }

    let d = `M ${pts[0].x} ${pts[0].y}`;
    for (let i = 1; i < pts.length; i++) {
      d += ` L ${pts[i].x} ${pts[i].y}`;
    }
    return d;
  };

  const clicksPath = buildPath(lineProgress);

  // Label animations
  const labelProgress = spring({ frame, fps, delay: 60, config: { damping: 200 } });

  const arrowProgress = spring({ frame, fps, delay: 80, config: { damping: 200 } });

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          paddingBottom: 160,
        }}
      >
        {/* Chart container */}
        <div
          style={{
            opacity: interpolate(overallIn, [0, 1], [0, 1]),
            transform: `translateY(${interpolate(overallIn, [0, 1], [40, 0])}px)`,
          }}
        >
          <svg
            width={chartW + 120}
            height={chartH + 120}
            viewBox={`-60 -60 ${chartW + 120} ${chartH + 120}`}
          >
            {/* Grid lines */}
            {[0, 0.25, 0.5, 0.75, 1].map((t, i) => (
              <line
                key={i}
                x1={0}
                y1={t * chartH}
                x2={chartW}
                y2={t * chartH}
                stroke="rgba(255,255,255,0.06)"
                strokeWidth={1.5}
              />
            ))}

            {/* Axes */}
            <line
              x1={0}
              y1={0}
              x2={0}
              y2={chartH}
              stroke="rgba(255,255,255,0.15)"
              strokeWidth={2}
            />
            <line
              x1={0}
              y1={chartH}
              x2={chartW}
              y2={chartH}
              stroke="rgba(255,255,255,0.15)"
              strokeWidth={2}
            />

            {/* Clicks line */}
            {clicksPath && (
              <>
                {/* Glow */}
                <path
                  d={clicksPath}
                  fill="none"
                  stroke={COLORS.red}
                  strokeWidth={10}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  opacity={0.2}
                />
                <path
                  d={clicksPath}
                  fill="none"
                  stroke={COLORS.red}
                  strokeWidth={4}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </>
            )}

            {/* Dot at end of line */}
            {lineProgress > 0.05 && (() => {
              const progIdx = lineProgress * (clicksPoints.length - 1);
              const idx = Math.min(Math.floor(progIdx), clicksPoints.length - 2);
              const frac = progIdx - idx;
              const a = getXY(clicksPoints[idx]);
              const b = getXY(clicksPoints[Math.min(idx + 1, clicksPoints.length - 1)]);
              const cx = a.x + (b.x - a.x) * frac;
              const cy = a.y + (b.y - a.y) * frac;
              return (
                <>
                  <circle cx={cx} cy={cy} r={14} fill={COLORS.red} opacity={0.3} />
                  <circle cx={cx} cy={cy} r={7} fill={COLORS.red} />
                </>
              );
            })()}
          </svg>
        </div>

        {/* Down arrow + label */}
        <div
          style={{
            position: "absolute",
            right: 680,
            bottom: 320,
            display: "flex",
            alignItems: "center",
            gap: 20,
            opacity: labelProgress,
            transform: `translateX(${interpolate(labelProgress, [0, 1], [30, 0])}px)`,
          }}
        >
          <div
            style={{
              width: 64,
              height: 64,
              borderRadius: "50%",
              backgroundColor: "rgba(255,71,87,0.15)",
              border: `2px solid ${COLORS.red}`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              transform: `rotate(${interpolate(arrowProgress, [0, 1], [-90, 0])}deg)`,
            }}
          >
            <svg width={28} height={28} viewBox="0 0 24 24" fill="none">
              <path
                d="M12 5v14M5 12l7 7 7-7"
                stroke={COLORS.red}
                strokeWidth={2.5}
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </div>
          <span
            style={{
              fontSize: 42,
              fontWeight: 700,
              color: COLORS.red,
              letterSpacing: "-0.01em",
            }}
          >
            Clicks
          </span>
        </div>

        {/* Impressions up indicator */}
        <div
          style={{
            position: "absolute",
            left: 680,
            top: 420,
            display: "flex",
            alignItems: "center",
            gap: 20,
            opacity: spring({ frame, fps, delay: 90, config: { damping: 200 } }),
            transform: `translateX(${interpolate(
              spring({ frame, fps, delay: 90, config: { damping: 200 } }),
              [0, 1],
              [-30, 0]
            )}px)`,
          }}
        >
          <div
            style={{
              width: 64,
              height: 64,
              borderRadius: "50%",
              backgroundColor: "rgba(0,212,170,0.15)",
              border: `2px solid ${COLORS.green}`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <svg width={28} height={28} viewBox="0 0 24 24" fill="none">
              <path
                d="M12 19V5M5 12l7-7 7 7"
                stroke={COLORS.green}
                strokeWidth={2.5}
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </div>
          <span
            style={{
              fontSize: 42,
              fontWeight: 700,
              color: COLORS.green,
              letterSpacing: "-0.01em",
            }}
          >
            Impressions
          </span>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

